/// The database DATABASE_URL names, through Fluent. It never migrates: the database already exists.
public final class AppDatabase: Sendable {
    public static let defaultURL = "postgres://app:app@localhost:5432/app"

    private let databases: Databases
    /// What the repositories run their queries on.
    public let database: any Database

    /// The database at url (DATABASE_URL, or defaultURL, by default).
    public convenience init(url: String = ProcessInfo.processInfo.environment["DATABASE_URL"] ?? AppDatabase.defaultURL) throws {
        try self.init(configuration: .postgres(url: url))
    }

    /// The database a configuration of Fluent names.
    public init(configuration: DatabaseConfigurationFactory) {
        let databases = Databases(threadPool: .singleton, on: MultiThreadedEventLoopGroup.singleton)
        databases.use(configuration, as: DatabaseID(string: "app"))
        self.databases = databases
        self.database = databases.database(logger: Logger(label: "app.database"), on: MultiThreadedEventLoopGroup.singleton.any())!
    }

    /// Closes the connections.
    public func shutdown() async {
        await databases.shutdownAsync()
    }
}

/// A page of a list: the rows from an offset, and how many there are in all.
public struct Page<T: Sendable>: Sendable {
    public let items: [T]
    public let total: Int
    public let offset: Int
    public let limit: Int

    public init(items: [T], total: Int, offset: Int, limit: Int) {
        self.items = items
        self.total = total
        self.offset = offset
        self.limit = limit
    }

    /// The same page with every row turned into something else.
    public func map<R: Sendable>(_ transform: (T) throws -> R) rethrows -> Page<R> {
        Page<R>(items: try items.map(transform), total: total, offset: offset, limit: limit)
    }
}

/// A field of an update: absent (it keeps its value), or set to a value, which may be nil.
public enum Patch<T: Sendable>: Sendable {
    case absent
    case set(T)

    /// The value given, or nil when the field is absent.
    public var given: T? {
        switch self {
        case .absent: nil
        case .set(let value): value
        }
    }
}

