/// Rows for the tests: valid values for every column, and the rows they point to.
enum Factories {
    /// A valid Customer that is not stored yet; n makes its unique values differ.
    static func newCustomer(_ n: Int) -> Customer {
        Customer(email: "email-\(n)", passwordHash: "passwordhash-\(n)")
    }

    /// A stored Customer.
    @discardableResult
    static func addCustomer(_ uow: any UnitOfWork, _ n: Int) async throws -> Customer {
        let entity = newCustomer(n)
        return try await uow.customers.insert(entity)
    }

    /// A valid Category that is not stored yet; n makes its unique values differ.
    static func newCategory(_ n: Int) -> Category {
        Category(name: "name-\(n)")
    }

    /// A stored Category.
    @discardableResult
    static func addCategory(_ uow: any UnitOfWork, _ n: Int) async throws -> Category {
        let entity = newCategory(n)
        return try await uow.categories.insert(entity)
    }

    /// A valid Product that is not stored yet; n makes its unique values differ.
    static func newProduct(_ n: Int) -> Product {
        Product(name: "name-\(n)", price: Decimal(string: "\(n % 10000).50")!, status: "status-\(n)", version: n)
    }

    /// A stored Product, with the rows it points to.
    @discardableResult
    static func addProduct(_ uow: any UnitOfWork, _ n: Int) async throws -> Product {
        let parent0 = try await addCategory(uow, n)
        var entity = newProduct(n)
        entity.categoryId = parent0.id
        return try await uow.products.insert(entity)
    }

    /// A valid Order that is not stored yet; n makes its unique values differ.
    static func newOrder(_ n: Int) -> Order {
        Order()
    }

    /// A stored Order, with the rows it points to.
    @discardableResult
    static func addOrder(_ uow: any UnitOfWork, _ n: Int) async throws -> Order {
        let parent0 = try await addCustomer(uow, n)
        var entity = newOrder(n)
        entity.customerId = parent0.id
        return try await uow.orders.insert(entity)
    }

    /// A valid OrderLine that is not stored yet; n makes its unique values differ.
    static func newOrderLine(_ n: Int) -> OrderLine {
        OrderLine(line: n, quantity: n)
    }

    /// A stored OrderLine, with the rows it points to.
    @discardableResult
    static func addOrderLine(_ uow: any UnitOfWork, _ n: Int) async throws -> OrderLine {
        let parent0 = try await addOrder(uow, n)
        let parent1 = try await addProduct(uow, n)
        var entity = newOrderLine(n)
        entity.orderId = parent0.id
        entity.productId = parent1.id
        return try await uow.orderLines.insert(entity)
    }

    /// A valid Tag that is not stored yet; n makes its unique values differ.
    static func newTag(_ n: Int) -> Tag {
        Tag(label: "label-\(n)")
    }

    /// A stored Tag.
    @discardableResult
    static func addTag(_ uow: any UnitOfWork, _ n: Int) async throws -> Tag {
        let entity = newTag(n)
        return try await uow.tags.insert(entity)
    }

    /// A valid ProductTag that is not stored yet; n makes its unique values differ.
    static func newProductTag(_ n: Int) -> ProductTag {
        ProductTag()
    }

    /// A stored ProductTag, with the rows it points to.
    @discardableResult
    static func addProductTag(_ uow: any UnitOfWork, _ n: Int) async throws -> ProductTag {
        let parent0 = try await addProduct(uow, n)
        let parent1 = try await addTag(uow, n)
        var entity = newProductTag(n)
