import FluentKit
import FluentSQL
import Foundation
import Testing
@testable import FluentPostgresqlRepositoryCommits

/// Every test is in this suite, one after another: they all empty the same database.
@Suite(.serialized) struct DataTests {}

/// The test database: the PostgreSQL database TEST_DATABASE_URL names, created again before every test.
enum TestDatabase {
    /// Runs body with the repositories over the test database, with every table dropped and created again first.
    static func with(_ body: (SqlUnitOfWork) async throws -> Void) async throws {
        // The tables are written for one kind of database: the tests cannot fall back to SQLite
        let url = try #require(ProcessInfo.processInfo.environment["TEST_DATABASE_URL"], "The database tests need a disposable PostgreSQL database: set TEST_DATABASE_URL (it is emptied)")
        let app = try AppDatabase(url: url)
        do {
            try await recreate(app.database)
            try await body(SqlUnitOfWork(db: app.database))
        } catch {
            await app.shutdown()
            throw error
        }
        await app.shutdown()
    }

    /// Drops every table, the rows that point to others first, and creates them again as the database has them.
    private static func recreate(_ db: any Database) async throws {
        let sql = db as! any SQLDatabase
        try await sql.raw("DROP TABLE IF EXISTS \"audit_log\" CASCADE").run()
        try await sql.raw("DROP TABLE IF EXISTS \"product_tags\" CASCADE").run()
        try await sql.raw("DROP TABLE IF EXISTS \"tags\" CASCADE").run()
        try await sql.raw("DROP TABLE IF EXISTS \"order_lines\" CASCADE").run()
        try await sql.raw("DROP TABLE IF EXISTS \"orders\" CASCADE").run()
        try await sql.raw("DROP TABLE IF EXISTS \"products\" CASCADE").run()
        try await sql.raw("DROP TABLE IF EXISTS \"categories\" CASCADE").run()
        try await sql.raw("DROP TABLE IF EXISTS \"customers\" CASCADE").run()
        try await db.schema("customers")
            .field("id", .int64, .identifier(auto: true))
            .field("email", .sql(unsafeRaw: "VARCHAR(120)"), .required)
            .field("password_hash", .string, .required)
            .field("created_at", .sql(unsafeRaw: "TIMESTAMPTZ"), .required, .sql(unsafeRaw: "DEFAULT CURRENT_TIMESTAMP"))
            .unique(on: "email", name: "uq_customers_email")
            .create()
        try await db.schema("categories")
            .field("id", .int64, .identifier(auto: true))
            .field("name", .sql(unsafeRaw: "VARCHAR(60)"), .required)
            .unique(on: "name")
            .create()
        try await db.schema("products")
            .field("id", .int64, .identifier(auto: true))
            .field("category_id", .int64, .required)
            .field("name", .sql(unsafeRaw: "VARCHAR(100)"), .required)
            .field("price", .sql(unsafeRaw: "DECIMAL(10, 2)"), .required)
            .field("status", .sql(unsafeRaw: "VARCHAR(10)"), .required)
            .field("version", .int32, .required, .sql(unsafeRaw: "DEFAULT 1"))
            .field("deleted_at", .sql(unsafeRaw: "TIMESTAMPTZ"))
            .foreignKey("category_id", references: "categories", "id", onDelete: .noAction, name: "fk_products_category")
            .create()
        try await db.schema("orders")
            .field("id", .int64, .identifier(auto: true))
            .field("customer_id", .int64, .required)
            .field("placed_at", .sql(unsafeRaw: "TIMESTAMPTZ"), .required, .sql(unsafeRaw: "DEFAULT CURRENT_TIMESTAMP"))
            .foreignKey("customer_id", references: "customers", "id", onDelete: .noAction)
            .create()
        try await db.schema("order_lines")
            .field("order_id", .int64, .required)
            .field("line", .int32, .required)
            .field("product_id", .int64, .required)
            .field("quantity", .int32, .required)
            .compositeIdentifier(over: "order_id", "line")
            .foreignKey("order_id", references: "orders", "id", onDelete: .cascade)
            .foreignKey("product_id", references: "products", "id", onDelete: .restrict)
            .create()
        try await db.schema("tags")
            .field("id", .int64, .identifier(auto: true))
            .field("label", .sql(unsafeRaw: "VARCHAR(30)"), .required)
            .create()
        try await db.schema("product_tags")
            .field("product_id", .int64, .required)
            .field("tag_id", .int64, .required)
            .compositeIdentifier(over: "product_id", "tag_id")
            .foreignKey("product_id", references: "products", "id", onDelete: .cascade)
            .foreignKey("tag_id", references: "tags", "id", onDelete: .cascade)
            .create()
        try await db.schema("audit_log")
            .field("at", .sql(unsafeRaw: "TIMESTAMPTZ"), .required)
            .field("message", .string, .required)
            .create()
    }
}

/// The DomainError work throws, or nil when it throws none.
func refusal<T>(_ work: () async throws -> T) async -> DomainError? {
    do {
        _ = try await work()
        return nil
    } catch let error as DomainError {
        return error
    } catch {
        return nil
    }
}

func isConflict(_ error: DomainError?) -> Bool {
    if case .some(.conflict) = error { true } else { false }
}

func isNotFound(_ error: DomainError?) -> Bool {
    if case .some(.notFound) = error { true } else { false }
}

